select fos_nastavi_urnik(z.id, u.id) from fos_zaposleni z, fos_urniki u where z.visible and lower(z.ime) = lower('Ljubiša') and lower(z.priimek) = lower('Živanič') and u.visible and u.ime = 'REŽIJA - GIBLJIVO' and not exists (select 1 from ln_fos_zaposleni_urniki l where l.id_zaposlenega = z.id and l.visible);

-- Preverjanje
select count(*) filter (where st_kartice is not null) as s_kartico, count(*) as vseh from fos_zaposleni where visible;
select u.ime as urnik, count(l.id) as oseb from fos_urniki u left join ln_fos_zaposleni_urniki l on l.id_urnika = u.id and l.visible where u.visible group by u.ime;
